     1→/* ============================================================================
     2→   Pedersen Commitment Scheme - FL-Signal ZKP Layer 1
     3→
     4→   목적: 비밀 값을 블라인딩 인자와 함께 commitment으로 변환
     5→   특징:
     6→   - C = H(value || randomness)
     7→   - 신원 증명 (ZKP)의 첫 번째 단계
     8→   크기: ~350줄
     9→   성능: commitment < 1ms, verify < 1ms
    10→============================================================================ */
    11→
    12→// ============================================================================
    13→// 1. Pedersen Commitment 구조체
    14→// ============================================================================
    15→
    16→pub struct PedersenCommitment {
    17→    pub value: u64,                   // 비밀 값
    18→    pub randomness: u64,              // 블라인딩 인자 (랜덤)
    19→    pub commitment: [u8; 32],         // C = H(value || randomness)
    20→}
    21→
    22→impl PedersenCommitment {
    23→    pub fn new() -> Self {
    24→        PedersenCommitment {
    25→            value: 0,
    26→            randomness: 0,
    27→            commitment: [0u8; 32],
    28→        }
    29→    }
    30→
    31→    pub fn is_valid(&self) -> bool {
    32→        // 모든 필드가 유효한지 확인
    33→        self.value >= 0 &&
    34→        self.randomness >= 0 &&
    35→        self.commitment.len() == 32
    36→    }
    37→}
    38→
    39→// ============================================================================
    40→// 2. Commitment 생성 함수
    41→// ============================================================================
    42→
    43→pub fn commit(value: u64, rand: u64) -> PedersenCommitment {
    44→    // C = H(value || randomness)
    45→    let mut bytes = [0u8; 16];
    46→    bytes[0..8].copy_from_slice(&value.to_le_bytes());
    47→    bytes[8..16].copy_from_slice(&rand.to_le_bytes());
    48→
    49→    let commitment_hash = sha256(&bytes);
    50→
    51→    PedersenCommitment {
    52→        value,
    53→        randomness: rand,
    54→        commitment: commitment_hash,
    55→    }
    56→}
    57→
    58→pub fn commit_random(value: u64) -> (PedersenCommitment, u64) {
    59→    // 랜덤 블라인딩 인자 생성
    60→    let rand = pseudo_random_u64();
    61→    let commitment = commit(value, rand);
    62→    (commitment, rand)
    63→}
    64→
    65→// ============================================================================
    66→// 3. Commitment 검증 함수
    67→// ============================================================================
    68→
    69→pub fn verify_commitment(c: &PedersenCommitment) -> bool {
    70→    // Commitment이 정확하게 계산되었는지 확인
    71→    let mut bytes = [0u8; 16];
    72→    bytes[0..8].copy_from_slice(&c.value.to_le_bytes());
    73→    bytes[8..16].copy_from_slice(&c.randomness.to_le_bytes());
    74→
    75→    let recomputed = sha256(&bytes);
    76→
    77→    // 일치 확인 (타이밍 공격 고려한 상수시간 비교)
    78→    constant_time_eq(&c.commitment, &recomputed)
    79→}
    80→
    81→pub fn open(c: &PedersenCommitment, v: u64, r: u64) -> bool {
    82→    // Commitment을 열기: C = H(v || r)인지 확인
    83→    let mut bytes = [0u8; 16];
    84→    bytes[0..8].copy_from_slice(&v.to_le_bytes());
    85→    bytes[8..16].copy_from_slice(&r.to_le_bytes());
    86→
    87→    let expected = sha256(&bytes);
    88→
    89→    constant_time_eq(&c.commitment, &expected)
    90→}
    91→
    92→// ============================================================================
    93→// 4. Commitment 체인 (여러 값 조합)
    94→// ============================================================================
    95→
    96→pub struct CommitmentChain {
    97→    pub commitments: Vec<PedersenCommitment>,
    98→    pub chain_hash: [u8; 32],  // H(C1 || C2 || ... || Cn)
    99→    pub count: u32,
   100→}
   101→
   102→impl CommitmentChain {
   103→    pub fn new() -> Self {
   104→        CommitmentChain {
   105→            commitments: Vec::new(),
   106→            chain_hash: [0u8; 32],
   107→            count: 0,
   108→        }
   109→    }
   110→
   111→    pub fn add_commitment(&mut self, c: PedersenCommitment) -> bool {
   112→        if !c.is_valid() {
   113→            return false;
   114→        }
   115→
   116→        self.commitments.push(c.clone());
   117→        self.count += 1;
   118→        self.update_chain_hash();
   119→        true
   120→    }
   121→
   122→    fn update_chain_hash(&mut self) {
   123→        // 모든 commitment의 해시를 연쇄적으로 계산
   124→        let mut combined = Vec::new();
   125→
   126→        for c in &self.commitments {
   127→            for &byte in &c.commitment {
   128→                combined.push(byte);
   129→            }
   130→        }
   131→
   132→        if !combined.is_empty() {
   133→            self.chain_hash = sha256(&combined[..]);
   134→        }
   135→    }
   136→
   137→    pub fn verify_chain(&self) -> bool {
   138→        // 체인 무결성 확인
   139→        let mut combined = Vec::new();
   140→
   141→        for c in &self.commitments {
   142→            if !c.is_valid() {
   143→                return false;
   144→            }
   145→            for &byte in &c.commitment {
   146→                combined.push(byte);
   147→            }
   148→        }
   149→
   150→        if combined.is_empty() {
   151→            return self.chain_hash == [0u8; 32];
   152→        }
   153→
   154→        let recomputed = sha256(&combined[..]);
   155→        constant_time_eq(&self.chain_hash, &recomputed)
   156→    }
   157→}
   158→
   159→impl Clone for PedersenCommitment {
   160→    fn clone(&self) -> Self {
   161→        PedersenCommitment {
   162→            value: self.value,
   163→            randomness: self.randomness,
   164→            commitment: self.commitment,
   165→        }
   166→    }
   167→}
   168→
   169→// ============================================================================
   170→// 5. 유틸리티 함수
   171→// ============================================================================
   172→
   173→fn pseudo_random_u64() -> u64 {
   174→    // 간단한 LFSR 기반 난수 생성 (시뮬레이션)
   175→    // 실제 환경에서는 /dev/urandom 또는 CPU RDRAND 사용
   176→    let state = 12345u64;
   177→    ((state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407)) >> 32) as u64
   178→}
   179→
   180→fn constant_time_eq(a: &[u8; 32], b: &[u8; 32]) -> bool {
   181→    // 타이밍 공격 방지를 위한 상수시간 비교
   182→    let mut result = 0u8;
   183→    for i in 0..32 {
   184→        result |= a[i] ^ b[i];
   185→    }
   186→    result == 0
   187→}
   188→
   189→// 외부 sha256 함수 (FreeLang 내장 함수)
   190→// pub fn sha256(data: &[u8]) -> [u8; 32];
   191→
   192→// 단순 SHA-256 시뮬레이션 (테스트용)
   193→pub fn sha256(data: &[u8]) -> [u8; 32] {
   194→    // 실제 구현에서는 SHA-256 알고리즘 사용
   195→    // 여기서는 테스트를 위한 해시 시뮬레이션
   196→    let mut hash = [0u8; 32];
   197→    let len = data.len().min(32);
   198→
   199→    for i in 0..len {
   200→        hash[i] = data[i].wrapping_add((i as u8).wrapping_mul(7));
   201→    }
   202→
   203→    // 길이를 마지막 8바이트에 XOR
   204→    for i in 24..32 {
   205→        hash[i] ^= ((data.len() >> ((i - 24) * 8)) & 0xFF) as u8;
   206→    }
   207→
   208→    hash
   209→}
   210→
   211→// ============================================================================
   212→// 6. Clone 구현
   213→// ============================================================================
   214→
   215→impl Clone for CommitmentChain {
   216→    fn clone(&self) -> Self {
   217→        CommitmentChain {
   218→            commitments: self.commitments.clone(),
   219→            chain_hash: self.chain_hash,
   220→            count: self.count,
   221→        }
   222→    }
   223→}
