    56→pub struct L0NeuralNet {
    57→    pub w1: [[f32; 16]; 16],        // 입력 -> 은닉층
    58→    pub b1: [f32; 16],
    59→    pub w2: [[f32; 8]; 16],         // 은닉층 -> 출력 (4가지 위협 분류)
    60→    pub b2: [f32; 8],
    61→}
    62→
    63→impl L0NeuralNet {
    64→    pub fn new() -> Self {
    65→        L0NeuralNet {
    66→            w1: [[0.1f32; 16]; 16],
    67→            b1: [0.0f32; 16],
    68→            w2: [[0.1f32; 8]; 16],
    69→            b2: [0.0f32; 8],
    70→        }
    71→    }
    72→
    73→    pub fn forward(&self, input: &[f32; 16]) -> [f32; 8] {
    74→        // 은닉층: h = relu(W1 * x + b1)
    75→        let mut hidden = [0.0f32; 16];
    76→        for i in 0..16 {
    77→            let mut sum = self.b1[i];
    78→            for j in 0..16 {
    79→                sum += self.w1[i][j] * input[j];
    80→            }
    81→            hidden[i] = if sum > 0.0 { sum } else { 0.0 };  // ReLU
    82→        }
    83→
    84→        // 출력층: y = softmax(W2 * h + b2)
    85→        let mut logits = [0.0f32; 8];
    86→        for i in 0..8 {
    87→            let mut sum = self.b2[i];
    88→            for j in 0..16 {
    89→                sum += self.w2[i][j] * hidden[j];
    90→            }
    91→            logits[i] = sum;
    92→        }
    93→
    94→        // Softmax
    95→        let max = logits.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
    96→        let mut exp_sum = 0.0f32;
    97→        let mut exp_logits = [0.0f32; 8];
    98→
    99→        for i in 0..8 {
   100→            exp_logits[i] = ((logits[i] - max) as f32).exp();
   101→            exp_sum += exp_logits[i];
   102→        }
   103→
   104→        let mut output = [0.0f32; 8];
   105→        for i in 0..8 {
   106→            output[i] = exp_logits[i] / exp_sum;
   107→        }
   108→
   109→        output
   110→    }
   111→}
