   130→    pub ngram_len: usize,
   131→    pub ngram_counts: u32,
   132→}
   133→
   134→impl NgramAnalyzer {
   135→    pub fn new() -> Self {
   136→        NgramAnalyzer {
   137→            ngram_history: [0u8; 32],
   138→            ngram_len: 0,
   139→            ngram_counts: 0,
   140→        }
   141→    }
   142→
   143→    pub fn add_signal(&mut self, signal_code: u8) {
   144→        // 슬라이딩 윈도우: 신호 코드 추가
   145→        if self.ngram_len < 32 {
   146→            self.ngram_history[self.ngram_len] = signal_code;
   147→            self.ngram_len += 1;
   148→        } else {
   149→            // 오래된 항목 제거
   150→            for i in 0..31 {
   151→                self.ngram_history[i] = self.ngram_history[i + 1];
   152→            }
   153→            self.ngram_history[31] = signal_code;
   154→        }
   155→        self.ngram_counts += 1;
   156→    }
   157→
   158→    pub fn is_anomalous(&self) -> bool {
   159→        // 이상 탐지: 반복되는 패턴이 적으면 이상
   160→        if self.ngram_len < 3 {
   161→            return false;  // 데이터 부족
   162→        }
   163→
   164→        // Bigram (연속한 2개)이 반복되는지 확인
   165→        let mut bigram_repeats = 0;
   166→
   167→        for i in 1..self.ngram_len {
   168→            let prev = self.ngram_history[i - 1];
   169→            let curr = self.ngram_history[i];
   170→
   171→            // 같은 bigram이 3회 이상 나타나는지 확인
   172→            let mut count = 0;
   173→            for j in 0..self.ngram_len - 1 {
   174→                if self.ngram_history[j] == prev &&
   175→                   self.ngram_history[j + 1] == curr {
   176→                    count += 1;
   177→                }
   178→            }
   179→
   180→            if count >= 2 {  // 2회 이상 반복
   181→                bigram_repeats += 1;
   182→            }
   183→        }
   184→
   185→        // bigram 반복이 적으면 이상 (엔트로피가 높음)
   186→        bigram_repeats < 2
   187→    }
   188→}
