   213→impl SignalDetector {
   214→    pub fn new() -> Self {
   215→        SignalDetector {
   216→            nn: L0NeuralNet::new(),
   217→            ngram: NgramAnalyzer::new(),
   218→            ensemble_weights: [0.6, 0.3, 0.1],
   219→            threat_threshold: 0.5,
   220→            detections_made: 0,
   221→            threats_detected: 0,
   222→        }
   223→    }
   224→
   225→    /// 신호 분석 (< 10µs, 규칙 7)
   226→    pub fn analyze_signal(&mut self, signal_features: &[f32; 16]) -> SignalThreat {
   227→        self.detections_made += 1;
   228→
   229→        // Step 1: L0NN 추론 (< 10µs)
   230→        let nn_output = self.nn.forward(signal_features);
   231→
   232→        // Step 2: N-gram 이상 탐지 (규칙 기반)
   233→        let signal_code = self.extract_signal_code(signal_features);
   234→        self.ngram.add_signal(signal_code);
   235→        let is_anomalous = self.ngram.is_anomalous();
   236→
   237→        // Step 3: 앙상블 신뢰도 계산
   238→        // NN 신뢰도 (가장 높은 클래스)
   239→        let nn_confidence = nn_output.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
   240→
   241→        // 규칙 기반 신뢰도 (N-gram 패턴)
   242→        let rule_confidence = if is_anomalous { 0.8 } else { 0.2 };
   243→
   244→        // 이상치 점수 (신호 엔트로피)
   245→        let entropy = self.compute_signal_entropy(signal_features);
   246→
   247→        // 가중 앙상블: 0.6×NN + 0.3×규칙 + 0.1×이상치
   248→        let ensemble_confidence =
   249→            (self.ensemble_weights[0] * nn_confidence) +
   250→            (self.ensemble_weights[1] * rule_confidence) +
   251→            (self.ensemble_weights[2] * entropy);
   252→
   253→        // Step 4: 위협 분류
   254→        let threat = if ensemble_confidence < self.threat_threshold {
   255→            SignalThreat::Clean
   256→        } else {
   257→            // nn_output의 최대 인덱스로 위협 분류
   258→            let max_idx = nn_output
   259→                .iter()
   260→                .enumerate()
   261→                .max_by(|(_, &a), (_, &b)| a.partial_cmp(&b).unwrap())
   262→                .map(|(i, _)| i)
   263→                .unwrap_or(4);
   264→
   265→            match max_idx {
   266→                0 | 1 => SignalThreat::Jamming,    // 클래스 0-1: Jamming
   267→                2 | 3 => SignalThreat::Spoofing,   // 클래스 2-3: Spoofing
   268→                4 | 5 => SignalThreat::Replay,     // 클래스 4-5: Replay
   269→                _ => SignalThreat::Unknown,
   270→            }
   271→        };
   272→
   273→        if !matches!(threat, SignalThreat::Clean) {
   274→            self.threats_detected += 1;
   275→        }
   276→
   277→        threat
   278→    }
   279→
   280→    fn extract_signal_code(&self, features: &[f32; 16]) -> u8 {
   281→        // 특성 벡터를 신호 코드로 변환 (0-255)
   282→        let sum: f32 = features.iter().sum();
   283→        ((sum.abs() as u32) % 256) as u8
   284→    }
   285→
   286→    fn compute_signal_entropy(&self, features: &[f32; 16]) -> f32 {
   287→        // Shannon entropy 계산 (정규화된 특성)
   288→        let sum: f32 = features.iter().map(|x| x.abs()).sum();
   289→
   290→        if sum == 0.0 {
   291→            return 0.0;
   292→        }
   293→
   294→        let mut entropy = 0.0f32;
   295→
   296→        for &f in features {
   297→            let p = (f.abs() / sum).max(0.001);  // 최소값 설정
   298→            entropy -= p * p.ln();
   299→        }
   300→
   301→        // 정규화 (0-1 범위)
   302→        (entropy / 16.0_f32.ln()).min(1.0)
   303→    }
   304→
   305→    pub fn accuracy(&self) -> f32 {
   306→        if self.detections_made == 0 {
   307→            return 0.0;
   308→        }
   309→
   310→        (self.threats_detected as f32 / self.detections_made as f32) * 100.0
   311→    }
   312→}
   313→
   314→impl Clone for SignalDetector {
   315→    fn clone(&self) -> Self {
   316→        SignalDetector {
   317→            nn: self.nn.clone(),
   318→            ngram: self.ngram.clone(),
   319→            ensemble_weights: self.ensemble_weights,
   320→            threat_threshold: self.threat_threshold,
   321→            detections_made: self.detections_made,
   322→            threats_detected: self.threats_detected,
   323→        }
   324→    }
   325→}
