    18→// ============================================================================
    19→// 1. DAG 노드 구조체
    20→// ============================================================================
    21→
    22→pub struct DagNode {
    23→    pub node_id: u64,
    24→    pub parent_hash_1: [u8; 32],    // 첫 번째 부모 (genesis: [0;32])
    25→    pub parent_hash_2: [u8; 32],    // 두 번째 부모 (DAG 이중 참조)
    26→    pub tx_data: [u8; 256],         // 트랜잭션 데이터
    27→    pub tx_amount: u64,             // 거래 금액
    28→    pub nonce: u64,                 // 계정 nonce (이중지출 방지)
    29→    pub timestamp: u64,             // 타임스탬프 (ns)
    30→    pub self_hash: [u8; 32],        // H(parent1 || parent2 || tx_data || nonce || ts)
    31→    pub amount_commitment: [u8; 32], // Pedersen commitment (금액 은닉)
    32→    pub is_genesis: bool,           // 제네시스 노드 여부
    33→}
    34→
    35→impl DagNode {
    36→    /// DAG 노드 생성 (< 1ms)
    37→    pub fn new(
    38→        node_id: u64,
    39→        parent_hash_1: [u8; 32],
    40→        parent_hash_2: [u8; 32],
    41→        tx_data: [u8; 256],
    42→        tx_amount: u64,
    43→        nonce: u64,
    44→        timestamp: u64,
    45→    ) -> Self {
    46→        let mut node = DagNode {
    47→            node_id,
    48→            parent_hash_1,
    49→            parent_hash_2,
    50→            tx_data,
    51→            tx_amount,
    52→            nonce,
    53→            timestamp,
    54→            self_hash: [0u8; 32],
    55→            amount_commitment: [0u8; 32],
    56→            is_genesis: false,
    57→        };
    58→
    59→        // self_hash 계산: SHA-3-256(parent1 || parent2 || tx_data || nonce || timestamp)
    60→        node.self_hash = compute_dag_node_hash(&node);
    61→
    62→        // amount_commitment: 간단한 Pedersen 시뮬레이션
    63→        node.amount_commitment = compute_amount_commitment(tx_amount);
    64→
    65→        node
    66→    }
    67→
    68→    /// 제네시스 노드 생성
    69→    pub fn genesis(node_id: u64, timestamp: u64) -> Self {
    70→        let mut node = DagNode {
    71→            node_id,
    72→            parent_hash_1: [0u8; 32],
    73→            parent_hash_2: [0u8; 32],
    74→            tx_data: [0u8; 256],
    75→            tx_amount: 0,
    76→            nonce: 0,
    77→            timestamp,
    78→            self_hash: [0u8; 32],
    79→            amount_commitment: [0u8; 32],
    80→            is_genesis: true,
    81→        };
    82→
    83→        node.self_hash = compute_dag_node_hash(&node);
    84→        node
    85→    }
    86→
    87→    /// 부모 검증
    88→    pub fn has_valid_parents(&self) -> bool {
    89→        // 둘 다 [0;32]이면 제네시스
    90→        if self.parent_hash_1 == [0u8; 32] && self.parent_hash_2 == [0u8; 32] {
    91→            return self.is_genesis;
    92→        }
    93→
    94→        // 최소 하나의 부모는 0이 아니어야 함
    95→        self.parent_hash_1 != [0u8; 32] || self.parent_hash_2 != [0u8; 32]
    96→    }
    97→
    98→    /// 노드 무결성 검증
    99→    pub fn verify_integrity(&self) -> bool {
   100→        let computed_hash = compute_dag_node_hash(self);
   101→        computed_hash == self.self_hash
   102→    }
   103→
   104→    /// 클론
   105→    pub fn clone(&self) -> Self {
   106→        DagNode {
   107→            node_id: self.node_id,
   108→            parent_hash_1: self.parent_hash_1,
   109→            parent_hash_2: self.parent_hash_2,
   110→            tx_data: self.tx_data,
   111→            tx_amount: self.tx_amount,
   112→            nonce: self.nonce,
   113→            timestamp: self.timestamp,
   114→            self_hash: self.self_hash,
   115→            amount_commitment: self.amount_commitment,
