   121→// ============================================================================
   122→// 2. 해시 계산 (SHA-3-256 시뮬레이션)
   123→// ============================================================================
   124→
   125→fn compute_dag_node_hash(node: &DagNode) -> [u8; 32] {
   126→    // parent1 || parent2 || tx_data || nonce || timestamp 연결
   127→    let mut input = [0u8; 512];
   128→
   129→    // 복사 (간단한 시뮬레이션)
   130→    let mut idx = 0;
   131→
   132→    // parent_hash_1 (32바이트)
   133→    for i in 0..32 {
   134→        input[idx] = node.parent_hash_1[i];
   135→        idx += 1;
   136→    }
   137→
   138→    // parent_hash_2 (32바이트)
   139→    for i in 0..32 {
   140→        input[idx] = node.parent_hash_2[i];
   141→        idx += 1;
   142→    }
   143→
   144→    // tx_data (256바이트)
   145→    for i in 0..256 {
   146→        input[idx] = node.tx_data[i];
   147→        idx += 1;
   148→    }
   149→
   150→    // nonce (8바이트)
   151→    let nonce_bytes = node.nonce.to_le_bytes();
   152→    for i in 0..8 {
   153→        input[idx] = nonce_bytes[i];
   154→        idx += 1;
   155→    }
   156→
   157→    // timestamp (8바이트)
   158→    let ts_bytes = node.timestamp.to_le_bytes();
   159→    for i in 0..8 {
   160→        input[idx] = ts_bytes[i];
   161→        idx += 1;
   162→    }
   163→
   164→    // SHA-3-256 시뮬레이션 (간단한 해시 함수)
   165→    simple_sha3_256(&input[0..idx])
   166→}
   167→
   168→fn compute_amount_commitment(amount: u64) -> [u8; 32] {
   169→    // Pedersen commitment 시뮬레이션
   170→    // C = H(amount || random_point)
   171→    let amount_bytes = amount.to_le_bytes();
   172→
   173→    let mut input = [0u8; 40];
   174→    for i in 0..8 {
   175→        input[i] = amount_bytes[i];
   176→    }
   177→
   178→    // random_point 시뮬레이션 (32바이트)
   179→    for i in 0..32 {
   180→        input[8 + i] = ((amount as usize).wrapping_mul(i + 1) % 256) as u8;
   181→    }
   182→
   183→    simple_sha3_256(&input)
   184→}
   185→
   186→fn simple_sha3_256(data: &[u8]) -> [u8; 32] {
   187→    // SHA-3-256 시뮬레이션 (MurmurHash 기반)
   188→    let mut hash = [0u8; 32];
   189→    let mut state = 0u64;
   190→
   191→    for &byte in data {
   192→        state = state.wrapping_mul(6364136223846793005)
   193→            .wrapping_add(1442695040888963407);
   194→        state ^= byte as u64;
   195→    }
   196→
   197→    // state를 32바이트로 확장
   198→    for i in 0..32 {
   199→        hash[i] = ((state.wrapping_add((i as u64) * 31)) >> (i % 8)) as u8;
   200→    }
   201→
   202→    hash
   203→}
