    55→// 2. Zero-Copy Ring Buffer (Phase 8 패턴)
    56→// ============================================================================
    57→
    58→pub struct ZeroCopyRingBuffer {
    59→    pub buffer: [Option<TxEvent>; 4096],
    60→    pub write_idx: u32,
    61→    pub read_idx: u32,
    62→    pub capacity: u32,
    63→    pub total_events: u64,
    64→}
    65→
    66→impl ZeroCopyRingBuffer {
    67→    pub fn new() -> Self {
    68→        ZeroCopyRingBuffer {
    69→            buffer: [None; 4096],
    70→            write_idx: 0,
    71→            read_idx: 0,
    72→            capacity: 4096,
    73→            total_events: 0,
    74→        }
    75→    }
    76→
    77→    /// O(1) 이벤트 투입
    78→    pub fn push(&mut self, event: TxEvent) -> bool {
    79→        let write_pos = self.write_idx as usize;
    80→
    81→        // 버퍼 가득 차면 oldest 항목 덮어쓰기
    82→        self.buffer[write_pos] = Some(event);
    83→        self.write_idx = (self.write_idx + 1) % self.capacity;
    84→        self.total_events += 1;
    85→
    86→        true
    87→    }
    88→
    89→    /// O(1) 이벤트 추출
    90→    pub fn pop(&mut self) -> Option<TxEvent> {
    91→        if self.read_idx == self.write_idx && self.buffer[self.read_idx as usize].is_none() {
    92→            return None;
    93→        }
    94→
    95→        let read_pos = self.read_idx as usize;
    96→        let event = self.buffer[read_pos].as_ref().map(|e| e.clone());
    97→
    98→        if event.is_some() {
    99→            self.buffer[read_pos] = None;
   100→            self.read_idx = (self.read_idx + 1) % self.capacity;
   101→        }
   102→
   103→        event
   104→    }
   105→
   106→    /// 버퍼 크기
   107→    pub fn len(&self) -> u32 {
   108→        let read_pos = self.read_idx;
   109→        let write_pos = self.write_idx;
   110→
   111→        if write_pos >= read_pos {
   112→            write_pos - read_pos
   113→        } else {
   114→            (self.capacity - read_pos) + write_pos
   115→        }
   116→    }
   117→
   118→    /// 버퍼 비어있는지 확인
   119→    pub fn is_empty(&self) -> bool {
   120→        self.len() == 0
   121→    }
   122→
   123→    /// 버퍼 가득 찼는지 확인
   124→    pub fn is_full(&self) -> bool {
   125→        self.len() >= self.capacity - 1
   126→    }
   127→
   128→    pub fn clone(&self) -> Self {
   129→        let mut new_buffer = [None; 4096];
   130→        for i in 0..4096 {
   131→            if let Some(event) = &self.buffer[i] {
   132→                new_buffer[i] = Some(event.clone());
   133→            }
   134→        }
   135→
   136→        ZeroCopyRingBuffer {
   137→            buffer: new_buffer,
   138→            write_idx: self.write_idx,
   139→            read_idx: self.read_idx,
   140→            capacity: self.capacity,
   141→            total_events: self.total_events,
   142→        }
   143→    }
   144→}
