   149→
   150→pub struct CommitBus {
   151→    pub ring: ZeroCopyRingBuffer,
   152→    pub commit_batch_size: u32,       // 배치 크기 (64)
   153→    pub committed_epochs: u64,        // 커밋된 에포크
   154→    pub committed_tx_count: u64,
   155→    pub pending_tx_count: u32,
   156→}
   157→
   158→impl CommitBus {
   159→    pub fn new() -> Self {
   160→        CommitBus {
   161→            ring: ZeroCopyRingBuffer::new(),
   162→            commit_batch_size: 64,
   163→            committed_epochs: 0,
   164→            committed_tx_count: 0,
   165→            pending_tx_count: 0,
   166→        }
   167→    }
   168→
   169→    /// 트랜잭션 투입 (O(1))
   170→    pub fn submit_tx(&mut self, event: TxEvent) -> bool {
   171→        if self.ring.push(event) {
   172→            self.pending_tx_count += 1;
   173→            return true;
   174→        }
   175→        false
   176→    }
   177→
   178→    /// 배치 커밋 (64개 트랜잭션)
   179→    pub fn commit_batch(&mut self) -> Vec<TxEvent> {
   180→        let mut batch = Vec::new();
   181→
   182→        for _ in 0..self.commit_batch_size {
   183→            if let Some(event) = self.ring.pop() {
   184→                batch.push(event);
   185→                self.committed_tx_count += 1;
   186→                if self.pending_tx_count > 0 {
   187→                    self.pending_tx_count -= 1;
   188→                }
   189→            } else {
   190→                break;
   191→            }
   192→        }
   193→
   194→        if batch.len() > 0 {
   195→            self.committed_epochs += 1;
   196→        }
   197→
   198→        batch
   199→    }
   200→
   201→    /// 배치 크기 설정 (기본 64)
   202→    pub fn set_batch_size(&mut self, size: u32) {
   203→        self.commit_batch_size = size.min(4096);
   204→    }
   205→
   206→    /// 대기 중인 트랜잭션 개수
   207→    pub fn pending_count(&self) -> u32 {
   208→        self.pending_tx_count
   209→    }
   210→
   211→    /// 처리량 (tx/s)
   212→    pub fn throughput_tps(&self) -> f32 {
   213→        if self.committed_epochs == 0 {
   214→            return 0.0;
   215→        }
   216→
   217→        // 시뮬레이션: 각 에포크 = 1ms
   218→        let seconds = (self.committed_epochs as f32) / 1000.0;
   219→        self.committed_tx_count as f32 / seconds
   220→    }
   221→
   222→    /// 배치 커밋 성공률
   223→    pub fn batch_success_rate(&self) -> f32 {
   224→        if self.committed_epochs == 0 {
   225→            return 0.0;
   226→        }
   227→
   228→        // 완전 배치 수 (64개 모두 커밋된)
   229→        let full_batches = self.committed_tx_count / (self.commit_batch_size as u64);
   230→        (full_batches as f32 / self.committed_epochs as f32) * 100.0
   231→    }
   232→
   233→    pub fn clone(&self) -> Self {
   234→        CommitBus {
   235→            ring: self.ring.clone(),
   236→            commit_batch_size: self.commit_batch_size,
   237→            committed_epochs: self.committed_epochs,
   238→            committed_tx_count: self.committed_tx_count,
   239→            pending_tx_count: self.pending_tx_count,
   240→        }
   241→    }
   242→}
